import React from "react";
import './row.css';

interface RowProps {
    word: string;
    resultCode: string;
}

const Row: React.FC<RowProps> = ({word, resultCode}) => {
    const styles = [
        { backgroundColor: 'rgb(18,18,19)' },
        { backgroundColor: 'rgb(181,159,59)', outline: '2px solid rgb(181,159,59)'},
        { backgroundColor: 'rgb(83,141,78)', outline: '2px solid rgb(83,141,78)'}
    ]

    const numberArray: number[] = resultCode.split('').map(Number);

    return(
        <>
            <div className="rowcontainer">
                <div style ={{...styles[numberArray[0]]}}>{word[0]}</div>
                <div style ={{...styles[numberArray[1]]}}>{word[1]}</div>
                <div style ={{...styles[numberArray[2]]}}>{word[2]}</div>
                <div style ={{...styles[numberArray[3]]}}>{word[3]}</div>
                <div style ={{...styles[numberArray[4]]}}>{word[4]}</div>
            </div>
        </>
    );
}

export default Row;
